  1→import { Head, Link, router } from '@inertiajs/react';
  2→import { AlertTriangle, Bell, CheckCircle2, Info, ShieldAlert } from 'lucide-react';
  3→import { useState } from 'react';
  4→import AppLayout from '@/layouts/app-layout';
  5→import type { BreadcrumbItem } from '@/types';
  6→
  7→interface Regulation {
  8→    id: number;
  9→    type: string;
 10→    severity: 'urgent' | 'warning' | 'info';
 11→    title: string;
 12→    description: string;
 13→    action_label: string | null;
 14→    action_url: string | null;
 15→    due_date: string | null;
 16→    is_read: boolean;
 17→    is_resolved: boolean;
 18→    created_at: string;
 19→}
 20→
 21→interface Props {
 22→    regulations: Regulation[];
 23→}
 24→
 25→const breadcrumbs: BreadcrumbItem[] = [
 26→    { title: 'Mi Explotación', href: '/dashboard' },
 27→    { title: 'Normativa', href: '/normativa' },
 28→];
 29→
 30→const severityConfig = {
 31→    urgent: {
 32→        icon: ShieldAlert,
 33→        label: 'Urgente',
 34→        badgeBg: 'bg-[#E53935]',
 35→        badgeText: 'text-white',
 36→        borderColor: 'border-l-[#E53935]',
 37→        countBg: 'bg-[#E53935]',
 38→    },
 39→    warning: {
 40→        icon: AlertTriangle,
 41→        label: 'Atención',
 42→        badgeBg: 'bg-[#FFF3E0]',
 43→        badgeText: 'text-[#E65100]',
 44→        borderColor: 'border-l-[#E65100]',
 45→        countBg: 'bg-[#E65100]',
 46→    },
 47→    info: {
 48→        icon: Info,
 49→        label: 'Información',
 50→        badgeBg: 'bg-[#E3F2FD]',
 51→        badgeText: 'text-[#1565C0]',
 52→        borderColor: 'border-l-[#1565C0]',
 53→        countBg: 'bg-[#1565C0]',
 54→    },
 55→};
 56→
 57→function timeAgo(dateString: string): string {
 58→    const now = new Date();
 59→    const date = new Date(dateString);
 60→    const diffMs = now.getTime() - date.getTime();
 61→    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
 62→    const diffDays = Math.floor(diffHours / 24);
 63→
 64→    if (diffHours < 1) return 'hace un momento';
 65→    if (diffHours < 24) return `hace ${diffHours}h`;
 66→    if (diffDays === 1) return 'ayer';
 67→    return `hace ${diffDays} días`;
 68→}
 69→
 70→function daysUntil(dateString: string): string | null {
 71→    const now = new Date();
 72→    const date = new Date(dateString);
 73→    const diffMs = date.getTime() - now.getTime();
 74→    const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
 75→
 76→    if (days < 0) return 'Vencido';
 77→    if (days === 0) return 'Hoy';
 78→    if (days === 1) return 'Mañana';
 79→    return `Quedan ${days} días`;
 80→}
 81→
 82→function AlertCard({ regulation }: { regulation: Regulation }) {
 83→    const config = severityConfig[regulation.severity];
 84→    const Icon = config.icon;
 85→
 86→    const markRead = () => {
 87→        if (!regulation.is_read) {
 88→            router.patch(`/api/regulations/${regulation.id}/read`, {}, { preserveScroll: true });
 89→        }
 90→    };
 91→
 92→    const markResolved = () => {
 93→        router.patch(`/api/regulations/${regulation.id}/resolve`, {}, { preserveScroll: true });
 94→    };
 95→
 96→    return (
 97→        <div
 98→            className={`border-2 border-black border-l-4 ${config.borderColor} ${!regulation.is_read ? 'bg-[#FAFAFA]' : 'bg-white'} w-full`}
 99→            onClick={markRead}
100→        >
101→            <div className="flex flex-col gap-3 p-4">
102→                <div className="flex items-center justify-between">
103→                    <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 text-xs font-bold ${config.badgeBg} ${config.badgeText}`}>
104→                        <Icon className="size-3" />
105→                        {config.label}
106→                    </span>
107→                    <span className="text-xs text-[#757575]">{timeAgo(regulation.created_at)}</span>
108→                </div>
109→
110→                <h3 className="text-sm font-bold">{regulation.title}</h3>
111→                <p className="text-sm leading-[1.4] text-[#757575]">{regulation.description}</p>
112→
113→                {regulation.due_date && (
114→                    <p className="text-xs font-semibold text-[#757575]">
115→                        Vence: {new Date(regulation.due_date).toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })}
116→                        {' · '}
117→                        <span className={regulation.severity === 'urgent' ? 'text-[#E53935]' : ''}>{daysUntil(regulation.due_date)}</span>
118→                    </p>
119→                )}
120→
121→                <div className="flex items-center gap-2">
122→                    {regulation.action_url && regulation.action_label && (
123→                        <Link
124→                            href={regulation.action_url}
125→                            className="inline-flex items-center gap-1 bg-[#E53935] px-3 py-2 text-xs font-bold text-white"
126→                        >
127→                            {regulation.action_label}
128→                        </Link>
129→                    )}
130→                    {!regulation.is_resolved && (
131→                        <button
132→                            onClick={(e) => { e.stopPropagation(); markResolved(); }}
133→                            className="inline-flex items-center gap-1 border-2 border-black px-3 py-2 text-xs font-semibold"
134→                        >
135→                            <CheckCircle2 className="size-3" />
136→                            Resolver
137→                        </button>
138→                    )}
139→                </div>
140→            </div>
141→        </div>
142→    );
143→}
