 3→namespace App\Http\Controllers;
 4→
 5→use App\Models\Regulation;
 6→use Illuminate\Http\Request;
 7→use Inertia\Inertia;
 8→use Inertia\Response;
 9→
10→class RegulationController extends Controller
11→{
12→    public function index(Request $request): Response
13→    {
14→        $exploitation = $request->user()->exploitations()->firstOrFail();
15→
16→        $regulations = Regulation::query()
17→            ->where('exploitation_id', $exploitation->id)
18→            ->orderByRaw("CASE severity WHEN 'urgent' THEN 1 WHEN 'warning' THEN 2 WHEN 'info' THEN 3 ELSE 4 END")
19→            ->latest()
20→            ->get();
21→
22→        $grouped = $regulations->groupBy('severity');
23→
24→        return Inertia::render('normativa/index', [
25→            'regulations' => $regulations,
26→            'grouped' => $grouped,
27→            'counts' => [
28→                'urgent' => $grouped->get('urgent')?->count() ?? 0,
29→                'warning' => $grouped->get('warning')?->count() ?? 0,
30→                'info' => $grouped->get('info')?->count() ?? 0,
31→            ],
32→        ]);
33→    }
34→}
